export function fitScore(school: School, gpa: string, sat: string): number {
  let score = 50;
  const gpaNum = parseFloat(gpa) || 0;
  const satNum = parseInt(sat) || 0;

  if (satNum >= school.sat) score += 20;
  else if (satNum >= school.sat - 50) score += 10;
  else score -= 15;

  if (gpaNum >= school.gpa) score += 15;
  else if (gpaNum >= school.gpa - 0.2) score += 5;
  else score -= 10;

  return Math.max(10, Math.min(99, Math.round(score)));
}

export function tierFor(school: School, gpa: string, sat: string): 'Reach' | 'Match' | 'Safety' {
  const score = fitScore(school, gpa, sat);
  const acceptRate = school.accept;
  if (acceptRate < 12 || score < 55) return 'Reach';
  if (score >= 70 && acceptRate > 25) return 'Safety';
  return 'Match';
}
